(46561, 'Psalms 49:18', 'Psalms', 49, 18, 'که څه هم هغه په ژوند کې بختور ګڼي خپل ځان صفت یې کیږي ځکه هر کار کې کامیاب وي هغه', 'که چه هم هغه په ژوند کې بختور ګنی خپل جان صفت یې کیزی جکه هر کار کې کامیاب وی هغه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_49_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46562, 'Psalms 49:19', 'Psalms', 49, 19, 'دی به په مرګ کې شي یوځای خپلو نیکونو سره هغوی به هېڅکله رڼا نه ویني', 'دی به په مرګ کې شی یوجای خپلو نیکونو سره هغوی به هېچکله رنا نه وینی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_49_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46563, 'Psalms 49:20', 'Psalms', 49, 20, 'انسان لري شان او شوکت خو هغه نه پوهیږي چې شي به مړ لکه څارویو په شان', 'انسان لری شان او شوکت خو هغه نه پوهیزی چې شی به مر لکه چارویو په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_49_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46564, 'Judges 15:1', 'Judges', 15, 1, 'څه موده وروسته د غنمو د لو په وخت کې شمشون د خپلې ښځې د لیدلو دپاره ورغی او هغې ته یې د سوغات په توګه یو سېرلی یووړ. شمشون د هغې پلار ته وویل: «زه غواړم چې د خپلې ښځې کوټې ته لاړ شم.» خو هغه ورته اجازه ورنه کړه چې دننه لاړ شي.', 'چه موده وروسته د غنمو د لو په وخت کې شمشون د خپلې شجې د لیدلو دپاره ورغی او هغې ته یې د سوغات په توګه یو سېرلی یوور. شمشون د هغې پلار ته وویل: «زه غوارم چې د خپلې شجې کوتې ته لار شم.» خو هغه ورته اجازه ورنه کره چې دننه لار شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_001.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1D6_H-2YH8pS06udAfXV9JRNMEYFrY8Zw&export=download', 1761237844, 1761237844),
(46565, 'Judges 15:2', 'Judges', 15, 2, 'هغه شمشون ته وویل: «ما په رښتیا فکر کاوه چې ته د هغې څخه کرکه کوې، نو هغه ما ستا ملګري ته ورکړه. خو د هغې کشره خور د هغې څخه ډېره ښایسته ده، د دې په ځای ته کولای شې د هغې سره واده وکړې.»', 'هغه شمشون ته وویل: «ما په رشتیا فکر کاوه چې ته د هغې چخه کرکه کوې، نو هغه ما ستا ملګری ته ورکره. خو د هغې کشره خور د هغې چخه دېره شایسته ده، د دې په جای ته کولای شې د هغې سره واده وکرې.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_002.mp3', 'https://drive.google.com/file/d/1ZyJ2IB4kPIbqHDKmAoxAvS7Tt221pWBs/preview', 1761237844, 1761237844),
(46566, 'Judges 15:3', 'Judges', 15, 3, 'شمشون وویل: «دا ځل چې په فلسطینیانو باندې هرڅه وکړم زه به بې ګناه یم!»', 'شمشون وویل: «دا جل چې په فلسطینیانو باندې هرچه وکرم زه به بې ګناه یم!»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_003.mp3', 'https://drive.google.com/uc?id=1uyoZz2b0Fn1Sek9cLN7G7tGQ_jMrXFB6&export=download', 1761237844, 1761237844),
(46567, 'Judges 15:4', 'Judges', 15, 4, 'نو هغه لاړ او درې سوه ګیدړان یې ونیول او یوه یوه جوړه یې لکۍ په لکۍ سره وتړل. بیا هغه د لکیو په هرې جوړې پورې یو یو څراغ وتاړه.', 'نو هغه لار او درې سوه ګیدران یې ونیول او یوه یوه جوره یې لکی په لکی سره وترل. بیا هغه د لکیو په هرې جورې پورې یو یو چراغ وتاره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_004.mp3', 'https://drive.google.com/file/d/1JrYOSMI-XDBV3iyYRtOKVWULPeIP8Fa6/preview', 1761237844, 1761237844),
(46568, 'Judges 15:5', 'Judges', 15, 5, 'بیا یې څراغونو ته اور واچاوه او ګیدړان یې د فلسطینیانو په ولاړو فصلونو کې خوشې کړل. هغه د ګېډیو انبارونه او ولاړ فصلونه د انګورو او زیتونو د باغونو سره وسوځول.', 'بیا یې چراغونو ته اور واچاوه او ګیدران یې د فلسطینیانو په ولارو فصلونو کې خوشې کرل. هغه د ګېدیو انبارونه او ولار فصلونه د انګورو او زیتونو د باغونو سره وسوجول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_005.mp3', 'https://drive.google.com/uc?id=12QMno7GVm36MPYP3tdHmIWV5hN5ILCq5&export=download', 1761237844, 1761237844),
(46569, 'Judges 15:6', 'Judges', 15, 6, 'کله چې فلسطینیانو پوښتنه وکړه چې «دا کار چا کړی دی؟» کوم چا هغوی خبر کړل چې «دا کار شمشون کړی دی، ځکه چې د هغه خسر چې د تمنې څخه دی، د شمشون ښځه د هغه ملګري ته واده کړې وه.» نو فلسطینیان لاړل او هغه ښځه او د هغې پلار یې ژوندي وسوځول.', 'کله چې فلسطینیانو پوشتنه وکره چې «دا کار چا کری دی؟» کوم چا هغوی خبر کرل چې «دا کار شمشون کری دی، جکه چې د هغه خسر چې د تمنې چخه دی، د شمشون شجه د هغه ملګری ته واده کرې وه.» نو فلسطینیان لارل او هغه شجه او د هغې پلار یې ژوندی وسوجول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_006.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1l4pudW6Np2sddxrb2_n1MRBBNDmMLw8q&export=download', 1761237844, 1761237844),
(46570, 'Judges 15:7', 'Judges', 15, 7, 'شمشون هغوی ته وویل: «څرنګه چې تاسو داسې کار کړی دی، نو زه قسم خورم چې ترڅو پورې مې ستاسو څخه د هغوی بدل نه وي اخیستی تر هغې پورې به ارام نه کښېنم.»', 'شمشون هغوی ته وویل: «چرنګه چې تاسو داسې کار کری دی، نو زه قسم خورم چې ترچو پورې مې ستاسو چخه د هغوی بدل نه وی اخیستی تر هغې پورې به ارام نه کشېنم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_007.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1SjB7EyFXineW5bnwP4sFTq0b4Xqz7kkd&export=download', 1761237844, 1761237844),
(46571, 'Judges 15:8', 'Judges', 15, 8, 'شمشون په هغوی باندې ډېره سخته حمله وکړه او ډېر کسان یې ورڅخه ووژل. بیا هغه لاړ او د عیطام د ګټ په سمڅه کې اوسېده.', 'شمشون په هغوی باندې دېره سخته حمله وکره او دېر کسان یې ورچخه ووژل. بیا هغه لار او د عیطام د ګت په سمچه کې اوسېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_008.mp3', 'https://drive.google.com/file/d/1KLixDCwYa0CjyaLcc4WcPjbtcMkY4LTk/preview', 1761237844, 1761237844),
(46572, 'Judges 15:9', 'Judges', 15, 9, 'فلسطینیان لاړل او د یهودا په سیمه کې یې خېمې ودرولې او د لحي په ښارګوټي باندې یې حمله وکړه.', 'فلسطینیان لارل او د یهودا په سیمه کې یې خېمې ودرولې او د لحی په شارګوتی باندې یې حمله وکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_009.mp3', 'https://drive.google.com/file/d/1lSbEMqSDd_SsJrOrrfEHZuV3kbFXaiCr/preview', 1761237844, 1761237844),
(46573, 'Judges 15:10', 'Judges', 15, 10, 'د یهودا خلکو پوښتنه وکړه: «تاسو ولې په مونږ باندې حمله کوئ؟» هغوی په ځواب کې وویل: «مونږ د دې دپاره راغلي یو چې شمشون ونیسو او هغه کار ورسره وکړو چې هغه زمونږ سره وکړ.»', 'د یهودا خلکو پوشتنه وکره: «تاسو ولې په مونز باندې حمله کوی؟» هغوی په جواب کې وویل: «مونز د دې دپاره راغلی یو چې شمشون ونیسو او هغه کار ورسره وکرو چې هغه زمونز سره وکر.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_010.mp3', 'https://drive.google.com/file/d/1gYP8hHrs2HmXR-umq_F3P_pRs5PCzJuI/preview', 1761237844, 1761237844),
(46574, 'Judges 15:11', 'Judges', 15, 11, 'نو د یهودا درې زره کسان د عیطام د ګټ سمڅې ته لاړل او شمشون ته یې وویل: «ته خبر نه یې چې فلسطینیان په مونږ باندې حکومت کوي؟ تا زمونږ سره څه وکړل؟» هغه په ځواب کې وویل: «کوم کار چې هغوی زما سره کړی ؤ، ما هم د هغوی سره هماغسې کار وکړ.»', 'نو د یهودا درې زره کسان د عیطام د ګت سمچې ته لارل او شمشون ته یې وویل: «ته خبر نه یې چې فلسطینیان په مونز باندې حکومت کوی؟ تا زمونز سره چه وکرل؟» هغه په جواب کې وویل: «کوم کار چې هغوی زما سره کری و، ما هم د هغوی سره هماغسې کار وکر.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_011.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1jlCB8-z0AIu9xdGINitfAJElQ5QS2UCH&export=download', 1761237844, 1761237844),
(46575, 'Judges 15:12', 'Judges', 15, 12, 'هغوی ورته وویل: «مونږ د دې دپاره راغلي یو چې تا وتړو او فلسطینیانو ته دې وسپارو.» شمشون وویل: «ماته قسم وخورئ چې تاسو به مې په خپله نه وژنئ.»', 'هغوی ورته وویل: «مونز د دې دپاره راغلی یو چې تا وترو او فلسطینیانو ته دې وسپارو.» شمشون وویل: «ماته قسم وخوری چې تاسو به مې په خپله نه وژنی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_012.mp3', 'https://drive.google.com/file/d/1Ie8so6nLGIZyf6NOw7B-uDrkIomloDyk/preview', 1761237844, 1761237844),
(46576, 'Judges 15:13', 'Judges', 15, 13, 'هغوی وویل: «سمه ده، مونږ به ستا لاسونه وتړو او هغوی ته به دې وسپارو. مونږ به تا نه وژنو.» نو هغوی په دوو نویو رسۍ ګانو باندې د هغه لاسونه وتړل او د ګټ څخه یې بېرته راوست.', 'هغوی وویل: «سمه ده، مونز به ستا لاسونه وترو او هغوی ته به دې وسپارو. مونز به تا نه وژنو.» نو هغوی په دوو نویو رسی ګانو باندې د هغه لاسونه وترل او د ګت چخه یې بېرته راوست.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_013.mp3', 'https://drive.google.com/uc?id=1HiOzLYNr3avywCrInMuOn5CsWl3agbe6&export=download', 1761237844, 1761237844),
(46577, 'Judges 15:14', 'Judges', 15, 14, 'کله چې شمشون لحي ته ورسېده، فلسطینیان په منډه د هغه خواته ورغلل او چیغې یې وهلې. ناڅاپه د څښتن روح هغه قوي کړ او هغه رسۍ ګانې یې چې د هغه لاسونه ورباندې تړل شوي وو لکه د سوځېدلي کتان په شان وشکولې او هغه ولوېدلې.', 'کله چې شمشون لحی ته ورسېده، فلسطینیان په منده د هغه خواته ورغلل او چیغې یې وهلې. ناچاپه د چشتن روح هغه قوی کر او هغه رسی ګانې یې چې د هغه لاسونه ورباندې ترل شوی وو لکه د سوجېدلی کتان په شان وشکولې او هغه ولوېدلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_014.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1J5TMG5_8tD4cNp587W3RATm5LJOicq0F&export=download', 1761237844, 1761237844),
(46578, 'Judges 15:15', 'Judges', 15, 15, 'بیا شمشون د یوه داسې خره د ژامې هډوکی پیدا کړ چې په هماغو نژدې وختونو کې مردار شوی ؤ. هغه خپل لاس وراوږد کړ، هغه یې راواخیست او زر تنه یې ورباندې ووژل.', 'بیا شمشون د یوه داسې خره د ژامې هدوکی پیدا کر چې په هماغو نژدې وختونو کې مردار شوی و. هغه خپل لاس وراوزد کر، هغه یې راواخیست او زر تنه یې ورباندې ووژل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_015.mp3', 'https://drive.google.com/uc?id=1s0-hj6uiDKBOoI1NKUC6XGyBwl_KFE23&export=download', 1761237844, 1761237844),
(46579, 'Judges 15:16', 'Judges', 15, 16, 'نو شمشون وویل: ما زر کسان ووژل د خره د ژامې په هډوکي باندې ما د مړو څخه جوړې ډېرۍ ګانې کړلې د خره د ژامې په هډوکي باندې', 'نو شمشون وویل: ما زر کسان ووژل د خره د ژامې په هدوکی باندې ما د مرو چخه جورې دېری ګانې کرلې د خره د ژامې په هدوکی باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_016.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qvO50kw-b9P2SNliXiQU0YlNroL8S_Wq&export=download', 1761237844, 1761237844),
(46580, 'Judges 15:17', 'Judges', 15, 17, 'کله چې هغه خپلې خبرې خلاصې کړې، نو د ژامې هډوکی یې په ځمکه وغورځاوه او هغه ځای یې د ژامې د هډوکي د غونډۍ په نوم یاد کړ.', 'کله چې هغه خپلې خبرې خلاصې کرې، نو د ژامې هدوکی یې په جمکه وغورجاوه او هغه جای یې د ژامې د هدوکی د غوندی په نوم یاد کر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_017.mp3', 'https://drive.google.com/file/d/1jLjHEU9SDwa-hroXYp4AZIUtYAwTFNDy/preview', 1761237844, 1761237844),
(46581, 'Judges 15:18', 'Judges', 15, 18, 'بیا شمشون ډېر تږی شو، نو هغه څښتن ته فریاد وکړ او ویې ویل: «تا خپل بنده ته داسې لوی بری ورکړ. ایا اوس به د تندې څخه مړ کېږم او دې کافرو فلسطینیانو ته به په لاس ورځم؟»', 'بیا شمشون دېر تزی شو، نو هغه چشتن ته فریاد وکر او ویې ویل: «تا خپل بنده ته داسې لوی بری ورکر. ایا اوس به د تندې چخه مر کېزم او دې کافرو فلسطینیانو ته به په لاس ورجم؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges015_verse_018.mp3', 'https://drive.google.com/uc?id=1Q9M1KczmsVQAQIFVrJa-txe0uTd8oWr5&export=download', 1761237844, 1761237844),
